    [Fact]
    public void BhvModels002ProjectManifestDeclaresANonEmptyDescription()
    {
        /* The package manifest must carry a description, wired from the spec's
           description with a generated fallback, so the NuGet listing is never blank. */
        var manifest = File.ReadAllText(
            Path.Combine(ProjectRoot().FullName, "src", "PetstoreClient", "PetstoreClient.csproj")
        );

        var match = System.Text.RegularExpressions.Regex.Match(
            manifest,
            "<Description>(.*?)</Description>",
            System.Text.RegularExpressions.RegexOptions.Singleline
        );

        Assert.True(match.Success, "the project file must declare a <Description>");
        var text = match
            .Groups[1]
            .Value.Replace("<![CDATA[", "", StringComparison.Ordinal)
            .Replace("]]>", "", StringComparison.Ordinal)
            .Trim();
        Assert.NotEmpty(text);
    }

